function locateSceneRetakeSegment(segment){const index=spec.clips.findIndex(clip=>clip.source==='primary'&&clip.start<=segment.start&&clip.end>=segment.end);const overlap=index>=0?index:spec.clips.findIndex(clip=>clip.source==='primary'&&clip.end>segment.start&&clip.start<segment.end);if(overlap<0){$('sceneRetakeStatus').textContent='当前剪辑没有覆盖该源片时间窗，请先加入成片素材。';return -1}selectClip(overlap);draw();const clip=spec.clips[overlap],local=Math.max(0,Math.min(clip.end-clip.start-.001,segment.start-clip.start));seek(offset(overlap)+local);$('sceneRetakeStatus').textContent=index>=0?`已定位第 ${overlap+1} 段。点击「局部重拍」可继续核对输入和费用。`:`已定位第 ${overlap+1} 段；当前片段覆盖范围不足，请先用「分割」调整到 ${segment.start.toFixed(2)}–${segment.end.toFixed(2)} 秒。`;return overlap}
function openSceneRetakeSegment(segment,intent){if(locateSceneRetakeSegment(segment)<0)return;RetakeUI.open();$('retakeIntent').value=(intent+(segment.note?`\n镜头备注：${segment.note}`:'')).slice(0,1600);$('retakeIntent').focus();$('sceneRetakeStatus').textContent='已打开局部重拍面板；点击「准备片段」后才会冻结输入和报价。'}
function paintSceneCandidateReview(context){const root=$('sceneRetakeSeamReview'),fields=$('sceneRetakeReviewFields'),note=$('sceneRetakeReviewNote'),saveButton=$('saveSceneRetakeReview'),statusNode=$('sceneRetakeReviewStatus');if(!root||!fields)return;const candidate=context?.candidate,available=!!candidate&&candidate.state==='completed'&&!context.stale&&Number(candidate.revision)===Number(project?.revision);sceneRetakeReviewContext=available?context:null;root.hidden=!available;fields.replaceChildren();if(!available){if(note)note.value='';if(statusNode)statusNode.textContent=candidate?.state==='completed'&&candidate.revision!==project?.revision?'当前剪辑版本已变化，请重新生成或准备候选。':'';return}const review=candidate.candidate_review||{},checks=review.checks||{},labels=[['product','商品外观与材质'],['motion','动作与镜头衔接'],['audio','原声与音量连续']];const options=[['not_reviewed','待核对'],['aligned','基本一致'],['deviation','存在问题'],['unavailable','无法判断']];for(const [key,labelText] of labels){const row=document.createElement('label');row.className='scene-retake-review-row';const text=document.createElement('span');text.textContent=labelText;const select=document.createElement('select');select.dataset.reviewKey=key;select.setAttribute('aria-label',labelText);for(const [value,textValue] of options){const option=document.createElement('option');option.value=value;option.textContent=textValue;select.append(option)}select.value=checks[key]||'not_reviewed';row.append(text,select);fields.append(row)}if(note)note.value=review.note||'';if(statusNode)statusNode.textContent=review.receipt_sha256?`已保存 · 候选 ${review.candidate_sha256.slice(0,12)} · 仍需完整回放和听音`:'尚未记录这份候选的接缝核对';if(saveButton){saveButton.disabled=false;saveButton.onclick=saveSceneCandidateReview}}
