  const at=data.at,shotId=String(data.shot_id||'');
  const window=(project?.creative_context?.scene_handoff?.shot_windows||[]).find(item=>item.shot_id===shotId);
  if(typeof at!=='number'||!Number.isFinite(at)||!window||at<Number(window.start)-.001||at>Number(window.end)+.001)return;
