 if(tool==='audio'){const index=spec.audio.findIndex(clip=>clip.source===source);if(index<0){pendingAudioSource=source;sourceLibraryLocation(source,'已定位画布音轨，点击「＋ 音轨」加入当前剪辑');return false}selectTimeline('audio',index);draw();await seek(spec.audio[index].at);if(epoch!==videoToolEpoch)return false;showInspector();$('start')?.focus({preventScroll:true});status('音轨剪辑：调整声音起止、时间轴位置与音量；修改可撤销。');return true}
