 if(epoch!==videoToolEpoch)return false;
 if(!spec.clips.some(c=>c.source===source)){pendingRetakeSource=source;sourceLibraryLocation(source,'已定位重拍来源，点击「＋ 画面」加入后选择 3–10 秒范围');return false}
