async function save(){
 const controller=new AbortController();let timer;
 status('正在保存剪辑…');
 // Bound both the response headers and body. An uncertain write is never retried.
 const timeout=new Promise((_,reject)=>{timer=setTimeout(()=>{controller.abort();reject(Error('保存响应超时，尚未确认成功。当前页面草稿已保留，请保持页面打开，网络恢复后核对保存状态。'))},30000)});
 try{
  const r=await Promise.race([request('/edit','PUT',{revision:project.revision,spec},{signal:controller.signal}),timeout]);
  project.revision=r.revision;project.spec=copy(r.spec);spec=r.spec;dirty=false;$('download').hidden=true;$('toCanvas').hidden=true;status('剪辑已保存');draw();
 }catch(error){
  if(error.status===0)throw Error('保存连接中断，尚未确认成功。当前页面草稿已保留，请保持页面打开，网络恢复后核对保存状态。');
  throw error;
 }finally{clearTimeout(timer)}
}
